import{_ as s,o as l,c as a,a2 as e}from"./chunks/framework.CdjpmwdR.js";const c=JSON.parse('{"title":"Windows 开发环境搭建：本机 + WSL + 沙盒集群","description":"本文给出一套可复用的 Windows 开发环境分层方案：桌面宿主机、WSL 开发层、VirtualBox 集群沙盒，兼顾日常编码效率与 K8s 调试能力。","frontmatter":{"category":"node","date":"2023-12-01","title":"Windows 开发环境搭建：本机 + WSL + 沙盒集群","description":"本文给出一套可复用的 Windows 开发环境分层方案：桌面宿主机、WSL 开发层、VirtualBox 集群沙盒，兼顾日常编码效率与 K8s 调试能力。","tags":["node","K8s"],"image":null},"headers":[],"relativePath":"blogs/2023/202312-windows-workspaces.md","filePath":"blogs/2023/202312-windows-workspaces.md"}'),n={name:"blogs/2023/202312-windows-workspaces.md"};function t(r,i,h,o,p,k){return l(),a("div",null,[...i[0]||(i[0]=[e(`<p>“不是 Mac 追不起，只是 Windows 更有性价比。”</p><p>实际原因是工作环境切换到 Windows，需要重建一套可长期维护的开发工作站。这里把配置方案整理成文档，便于复用和团队分享。</p><h2 id="前情提要" tabindex="-1">前情提要 <a class="header-anchor" href="#前情提要" aria-label="Permalink to &quot;前情提要&quot;">​</a></h2><p>作为“全干工程师”，工具链跨度很大。除了语言环境，还需要可折腾的 K8s 集群。所以我把 Windows 工作站分成三个层次：</p><ul><li>Windows 本机 <ul><li>宿主机，主要用于桌面软件的安装和使用，如：网页浏览、邮件收发、文档编辑</li><li>Yes：只能在 win 环境上操作的东西，No：代码开发、容器运行</li></ul></li><li>WSL 开发环境 <ul><li>开发机，Linux 环境，用于绝大多数的开发、运维工作</li><li>Yes：代码开发，No：桌面应用、沙盒集群、虚拟机</li></ul></li><li>VirtualBox 沙盒环境 <ul><li>沙盒环境，k8s-linux 集群，用于测试和 Debug 集群问题</li><li>Yes：测试集群、Debug，No：代码开发、桌面应用</li></ul></li></ul><p>划分之后，Windows 本机就是一个相对干净的环境，除了桌面软件和配置 Git 外，不会安装 SDK 和配置环境变量。WSL 则完全承接开发工作，并通过内网 IP 来调试 VirtualBox 中的集群。</p><h2 id="windows-本机" tabindex="-1">Windows 本机 <a class="header-anchor" href="#windows-本机" aria-label="Permalink to &quot;Windows 本机&quot;">​</a></h2><ol><li><p>安装必要的软件</p><p>即需要运行在 Windows 桌面环境的应用，根据个人使用情况选择和替换，如：</p><ul><li>Logseq（主要的知识库，用 OneDrive 做备份和同步）</li><li>Visual Studio Code（主要的编辑器，各种插件 YYDS）</li><li>Windows Terminal</li><li>WSL</li><li>VirtualBox</li><li>Vagrant（代码化操作 VM）</li><li>FlowLauncher（类似 Alfred，也可使用 uTools）</li><li>Clash</li></ul></li><li><p>开启虚拟化功能（为其他环境做准备）</p><p>Win 健 -&gt; Turn Windows feature on or off -&gt; 打开以下功能：</p><ul><li>Hyper-V</li><li>Virtual Machine Platform</li><li>Windows Subsystem for Linux</li></ul><p>也可以通过 Powershell 命令开启</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Enable-WindowsOptionalFeature</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Online </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FeatureName Microsoft</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Hyper</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">V </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">All</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Enable-WindowsOptionalFeature</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Online </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FeatureName VirtualMachinePlatform </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">All</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Enable-WindowsOptionalFeature</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Online </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FeatureName Microsoft</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Windows</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Subsystem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Linux</span></span></code></pre></div></li><li><p>其他设置</p><ul><li>！！墙裂建议升级到 Win11</li><li>通过快捷键操作 Snap 布局、虚拟桌面，体验比 Mac 还要好</li><li><a href="https://zhuanlan.zhihu.com/p/460274555" target="_blank" rel="noreferrer">非常实用的 Windows 11 键盘快捷键终极列表 - 知乎 (zhihu.com)</a></li><li>调整键盘速度：Win 健 -&gt; KeyBoard -&gt; Repeat delay / Repeat rate 拉满</li><li>开启世界时钟：时钟 -&gt; 世界时钟 -&gt; 增加城市（对于跨时区工作的同学很有帮助）</li></ul></li></ol><h2 id="wsl-开发环境" tabindex="-1">WSL 开发环境 <a class="header-anchor" href="#wsl-开发环境" aria-label="Permalink to &quot;WSL 开发环境&quot;">​</a></h2><ol><li><p>安装 WSL</p><p>WSL 的安装已经有非常多的文档，就不详述了。需要注意的是：</p><ul><li>如果安装的是 wsl 1，需要手动下载一个升级包</li><li><a href="https://learn.microsoft.com/zh-cn/windows/wsl/install#upgrade-version-from-wsl-1-to-wsl-2" target="_blank" rel="noreferrer">https://learn.microsoft.com/zh-cn/windows/wsl/install#upgrade-version-from-wsl-1-to-wsl-2</a></li><li><a href="https://learn.microsoft.com/zh-cn/windows/wsl/install-manual#step-3---enable-virtual-machine-feature" target="_blank" rel="noreferrer">https://learn.microsoft.com/zh-cn/windows/wsl/install-manual#step-3---enable-virtual-machine-feature</a></li><li>如果 Win 需要工作在 VPN 环境下，wsl 有一定概率出现网络问题</li><li><a href="https://github.com/sakai135/wsl-vpnkit" target="_blank" rel="noreferrer">sakai135/wsl-vpnkit: Provides network connectivity to WSL 2 when blocked by VPN (github.com)</a></li></ul></li><li><p>配置 WSL（Linux）</p><ul><li>安装 zsh，配置 zshrc <ul><li>主要是一些环境变量的配置：<a href="https://github.com/Anddd7/workspaces/blob/main/.initializer.win/wsl/zsh/.zshrc" target="_blank" rel="noreferrer">https://github.com/Anddd7/workspaces/blob/main/.initializer.win/wsl/zsh/.zshrc</a></li><li>很多工具都会往 zshrc 中写东西，建议安装完成后再来整理这个</li></ul></li><li>配置 gitconfig <ul><li>有多个账号/仓库的情况下，可以建立具有 hierarchy 结构的配置：<a href="https://github.com/Anddd7/workspaces/blob/main/.initializer.win/wsl/git/.gitconfig" target="_blank" rel="noreferrer">https://github.com/Anddd7/workspaces/blob/main/.initializer.win/wsl/git/.gitconfig</a></li><li>还可以在顶层引入全局的 githook 和 gitignore 来统一管理</li></ul></li><li>配置 ssh <ul><li><p>ssh clone 的时候需要，这里可以选择在 win 上生成 ssh key，然后复制到 wsl 中使用，就可以配一份 ssh 两边都能 clone</p></li><li><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/c/Users/your-user-name/.ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519</span></span></code></pre></div></li></ul></li></ul></li><li><p>准备开发环境</p><p>即安装各种开发工具和代码环境，可参考：<a href="https://github.com/Anddd7/workspaces/tree/main/.initializer.win/wsl" target="_blank" rel="noreferrer">https://github.com/Anddd7/workspaces/tree/main/.initializer.win/wsl</a></p><p>值得一提的是容器环境的安装，我选择的是 podman + k3s：<a href="https://github.com/Anddd7/workspaces/blob/main/.initializer.win/wsl/2_0_container.sh" target="_blank" rel="noreferrer">https://github.com/Anddd7/workspaces/blob/main/.initializer.win/wsl/2_0_container.sh</a></p><ul><li>podman</li><li>用于代替 docker，底层使用的是 crun 作为容器运行时</li><li>alias docker=podman，打镜像、运行测试容器</li><li>k3s</li><li>因为有 virtualbox 做沙盒环境，wsl 里只是想装一个最小化 k8s 用来验证 yaml 和部署流程的</li><li>但尝试了 minikube 和 kind，由于 cni 和 runtime 的问题各种报错</li><li>最后选择了 k3s 一键式安装，啪的一下就装好了，干净又卫生</li></ul></li></ol><h2 id="virtualbox-沙盒环境" tabindex="-1">VirtualBox 沙盒环境 <a class="header-anchor" href="#virtualbox-沙盒环境" aria-label="Permalink to &quot;VirtualBox 沙盒环境&quot;">​</a></h2><p>这一步主要是测试复杂的 k8s 集群，比如我现在要准备一个 Rancher 集群用于测试，如果在 wsl 里面搭建的话会相对麻烦，你需要安装和准备很多工具和运行时，而且还需要考虑和 wsl 的兼容性问题。</p><p>而在 VirtualBox 里面，你可以创建一台这样的机器，配置好之后复制多份就能搭建一个集群，非常方便。再加上使用 Vagrant 用脚本来描述机器的配置，就能够实现代码化的操作：<a href="https://github.com/rancher/quickstart/blob/master/rancher/vagrant/Vagrantfile%E3%80%82" target="_blank" rel="noreferrer">https://github.com/rancher/quickstart/blob/master/rancher/vagrant/Vagrantfile。</a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>总的来说，Windows 作为开发环境还是非常不错的，配置 WSL 的部分对于 Mac/Linux 用户来说基本没有难度。</p><p>最大的问题还是网络，比如 Proxy、VPN 环境下，需要在 Win 和 WSL 做一些额外的配置。</p>`,16)])])}const u=s(n,[["render",t]]);export{c as __pageData,u as default};
